import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"ADR-007: Caption bidi strategy (<bdi> isolation + tatweel joiner)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/007-caption-bidi-strategy.md","filePath":"adr/007-caption-bidi-strategy.md"}'),o={name:"adr/007-caption-bidi-strategy.md"};function r(s,e,d,c,l,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-007-caption-bidi-strategy-bdi-isolation-tatweel-joiner" tabindex="-1">ADR-007: Caption bidi strategy (<code>&lt;bdi&gt;</code> isolation + tatweel joiner) <a class="header-anchor" href="#adr-007-caption-bidi-strategy-bdi-isolation-tatweel-joiner" aria-label="Permalink to &quot;ADR-007: Caption bidi strategy (`&lt;bdi&gt;` isolation + tatweel joiner)&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-10-15</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Arabic captions with English terms break in naive renderers: words flip, &quot;الـ&quot; detaches from its noun, and punctuation lands on the wrong side.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ul><li>Consecutive Latin words merge into one token; a token ending in tatweel (الـ, بـ, للـ) joins the next with NO-BREAK SPACE.</li><li>Each token is an atomic inline-block (<code>white-space: nowrap</code>), so it behaves as one neutral object in the paragraph&#39;s bidi resolution; inside it, Latin runs are wrapped in <code>&lt;bdi&gt;</code>.</li><li>Trailing punctuation stays outside the isolate; the chunk&#39;s base direction is RTL when it has Arabic.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Visual order is correct by construction and verified by geometry tests and golden frames for every case of SRS §9.3. Captions never wrap inside a term.</p>',8)])])}const b=t(o,[["render",r]]);export{u as __pageData,b as default};
